// === Tab: mySketch ===
/*
	Plasma #WCCChallenge "Phenomena" //20260422 
	https://openprocessing.org/sketch/2923460
	#generativeart #creativecoding #p5js

	Dear Raph and creative coding community,

	interpreted the prompt as interferences of moving plasma sources.
	Evolutions will placed in a grid, depending on value STPS.
	This generates a pseudo dithering effect while allowing overlays.

	Would come to this idea without using loadPixels() as its slow.
   Have to update to shader for speed neither...

   Thank you Ai for converting it for me.
	Original source is in [old]-Tab

	Join the Birb's Nest Discord for friendly creative coding community
	and future challenges and contributions: https://discord.gg/S8c7qcjw2b
	WCCC-Contributions: https://openprocessing.org/curation/78544
*/

const NUM_SOURCES = 3;
const STPS = 4; // 2..6 — block size for the dither

// All STPS*STPS sub-cell offsets, shuffled once
let offsets = [];
let sources = [];
let plasmaShader;

function setup() {
    createCanvas(1920, 1080, WEBGL);
    frameRate(60);
    describe("interferences of moving plasma sources (shader, dithered)");
    //pixelDensity(1);
    noStroke();
    background(0, 0, 40); // navy-ish initial fill so empty cells aren't black

    plasmaShader = buildFilterShader(() => {
        const uTime       = uniformFloat('uTime');
        const uResolution = uniformVector2('uResolution');
        const uStps       = uniformFloat('uStps');
        const uOffset     = uniformVector2('uOffset'); // current sub-cell (ox, oy)

        const uSrc0 = uniformVector3('uSrc0');
        const uSrc1 = uniformVector3('uSrc1');
        const uSrc2 = uniformVector3('uSrc2');

        function waveFrom(s, px, py, t) {
            const dx = px - s.x;
            const dy = py - s.y;
            const d  = sqrt(dx * dx + dy * dy);
            return sin(d * s.z - t * 3.0);
        }

        getColor((inputs, canvasContent) => {
            // pixel coords (top-left origin)
            const px = inputs.texCoord.x * uResolution.x;
            const py = (1.0 - inputs.texCoord.y) * uResolution.y;

            // block-local position
            const bx = floor(px / uStps);
            const by = floor(py / uStps);
            const localX = floor(px - bx * uStps); // 0..STPS-1
            const localY = floor(py - by * uStps);

            // sample point for this block (top-left of block + offset)
            const sx = bx * uStps + uOffset.x;
            const sy = by * uStps + uOffset.y;

            // compute new plasma color at the sample point
            const w0 = waveFrom(uSrc0, sx, sy, uTime);
            const w1 = waveFrom(uSrc1, sx, sy, uTime);
            const w2 = waveFrom(uSrc2, sx, sy, uTime);
            const waveSum = w0 + w1 + w2;

            const v   = (waveSum / NUM_SOURCES) * 0.5 + 0.5;
            const h/*ue*/ = fract(v + uTime * (5.0 / 360.0));

            const kr = fract(h/*ue*/ + 1.0);
            const kg = fract(h/*ue*/ + 2.0 / 3.0);
            const kb = fract(h/*ue*/ + 1.0 / 3.0);

            const r = abs(kr * 6.0 - 3.0) - 1.0;
            const g = abs(kg * 6.0 - 3.0) - 1.0;
            const b = abs(kb * 6.0 - 3.0) - 1.0;

            const sat = 0.99;
            const val = 0.99;

            const newR = val * mix(1.0, max(0.0, min(1.0, r)), sat);
            const newG = val * mix(1.0, max(0.0, min(1.0, g)), sat);
            const newB = val * mix(1.0, max(0.0, min(1.0, b)), sat);

            // Read previous color at THIS pixel
            const prev = getTexture(canvasContent, inputs.texCoord);

            // Only update this pixel if it matches the current offset cell
            // (branchless using step: 1 when |localX-ox| < 0.5 AND |localY-oy| < 0.5)
            const matchX = step(abs(localX - uOffset.x), 0.5);
            const matchY = step(abs(localY - uOffset.y), 0.5);
            const match  = matchX * matchY;

            const outR = mix(prev.x, newR, match);
            const outG = mix(prev.y, newG, match);
            const outB = mix(prev.z, newB, match);

            return [outR, outG, outB, 1.0];
        });
    });

    buildOffsets();
    initSources();
}

function buildOffsets() {
    offsets = [];
    for (let y = 0; y < STPS; y++) {
        for (let x = 0; x < STPS; x++) {
            offsets.push([x, y]);
        }
    }
    shuffle(offsets, true);
}

function initSources() {
    sources = [];
    for (let i = 0; i < NUM_SOURCES; i++) {
        const cx = random(0.2, 0.8) * width;
        const cy = random(0.2, 0.8) * height;
        var r  = random(0.1, 0.3) * max(width, height);
        const a  = random(TAU);
        const da = random(0.012, 0.025) * Math.sign(random() - 0.5);
        const freq = random(0.015, 0.025);
        sources.push({ cx, cy, r, a, da, freq, x: cx, y: cy });
    }
}

function windowResized() {
    resizeCanvas(width, height);
    background(0, 0, 40);
    initSources();
}

function mouseClicked() {
    background(0, 0, 40);
    buildOffsets();
    initSources();
}

function draw() {
    for (const s of sources) {
        s.x = s.cx + cos(s.a) * s.r;
        s.y = s.cy + sin(s.a) * s.r;
        s.a += s.da;
    }

    const off = offsets[frameCount % (STPS * STPS)];

    plasmaShader.setUniform('uTime', millis() * 0.001);
    plasmaShader.setUniform('uResolution', [width, height]);
    plasmaShader.setUniform('uStps', STPS);
    plasmaShader.setUniform('uOffset', off);
    plasmaShader.setUniform('uSrc0', [sources[0].x, sources[0].y, sources[0].freq]);
    plasmaShader.setUniform('uSrc1', [sources[1].x, sources[1].y, sources[1].freq]);
    plasmaShader.setUniform('uSrc2', [sources[2].x, sources[2].y, sources[2].freq]);

    filter(plasmaShader);
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

